      'name: severity-based-priority-queues\ndescription: Route log messages to priority queues based on severity\ntype: pipeline\nnamespace: production\n\nconfig:\n  input:\n    http_server:\n      address: 0.0.0.0:8080\n      path: /logs\n      timeout: 5s\n      rate_limit: \'10000/s\'\n\n  pipeline:\n    processors:\n      # Classify priority based on severity\n      - mapping: |\n          root = if this.severity == null {\n            throw("Missing required field: severity")\n          } else {\n            this\n          }\n\n          # Normalize severity to uppercase\n          root.severity = this.severity.string().uppercase()\n\n          # Map severity to priority\n          root.priority = match root.severity {\n            "CRITICAL" => "critical"\n            "FATAL" => "critical"\n            "ERROR" => "high"\n            "WARNING" => "normal"\n            "WARN" => "normal"\n            "INFO" => "low"\n            "DEBUG" => "low"\n            "TRACE" => "low"\n            _ => "normal"\n          }\n\n          # Add priority score for metrics\n          root.priority_score = match root.priority {\n            "critical" => 100\n            "high" => 75\n            "normal" => 50\n            "low" => 25\n            _ => 0\n          }\n\n          root.processed_at = now()\n          root.edge_node_id = env("NODE_ID").or("unknown")\n\n  output:\n    switch:\n      retry_until_success: false\n\n      cases:\n        # Case 1: Critical priority - immediate delivery\n        - check: this.priority == "critical"\n          output:\n            label: critical_queue\n            kafka:\n              addresses: [\'${KAFKA_TLS_BROKERS}\']\n              topic: logs-critical\n              tls: &kafka_tls\n                enabled: true\n                root_cas_file: ${KAFKA_CA_FILE}\n              sasl: &kafka_sasl\n                mechanism: SCRAM-SHA-512\n                user: \'${KAFKA_USERNAME}\'\n                password: \'${KAFKA_PASSWORD}\'\n\n              # No batching - send immediately\n              batching:\n                count: 1\n                period: 0s\n\n              # Aggressive delivery guarantees\n              max_in_flight: 1\n              ack_replicas: true\n              idempotent_write: true\n\n              # Maximum retries for critical messages\n              max_retries: 10\n              backoff:\n                initial_interval: 100ms\n                max_interval: 2s\n\n        # Case 2: High priority - small batches, fast delivery\n        - check: this.priority == "high"\n          output:\n            label: high_priority_queue\n            kafka:\n              addresses: [\'${KAFKA_TLS_BROKERS}\']\n              topic: logs-high\n              tls: *kafka_tls\n              sasl: *kafka_sasl\n\n              # Small batches for fast delivery\n              batching:\n                count: 10\n                period: 1s\n\n              # Strong delivery guarantees\n              max_in_flight: 5\n              ack_replicas: true\n\n              # Moderate retries\n              max_retries: 5\n              backoff:\n                initial_interval: 500ms\n                max_interval: 5s\n\n              compression: snappy\n\n        # Case 3: Normal priority - standard batching\n        - check: this.priority == "normal"\n          output:\n            label: normal_queue\n            kafka:\n              addresses: [\'${KAFKA_TLS_BROKERS}\']\n              topic: logs-normal\n              tls: *kafka_tls\n              sasl: *kafka_sasl\n\n              # Standard batching for balanced throughput/latency\n              batching:\n                count: 100\n                period: 5s\n\n              # Balanced configuration\n              max_in_flight: 10\n\n              # Standard retries\n              max_retries: 3\n              backoff:\n                initial_interval: 1s\n                max_interval: 10s\n\n              compression: snappy\n\n        # Case 4: Low priority - large batches, deferred delivery\n        - check: this.priority == "low"\n          output:\n            label: low_priority_queue\n            kafka:\n              addresses: [\'${KAFKA_TLS_BROKERS}\']\n              topic: logs-low\n              tls: *kafka_tls\n              sasl: *kafka_sasl\n\n              # Large batches to minimize overhead\n              batching:\n                count: 1000\n                period: 1m\n\n              # High concurrency for throughput\n              max_in_flight: 20\n\n              # Minimal retries\n              max_retries: 1\n              backoff:\n                initial_interval: 5s\n                max_interval: 30s\n\n              # Aggressive compression for low-priority bulk data\n              compression: gzip\n\n        # Default: Treat unknown priorities as normal\n        - output:\n            kafka:\n              addresses: [\'${KAFKA_TLS_BROKERS}\']\n              topic: logs-normal\n              tls: *kafka_tls\n              sasl: *kafka_sasl\n              batching:\n                count: 100\n                period: 5s\n',
