        yamlFilename: "03-encrypt-pii-customer-data.yaml",
        yamlCode:
          'pipeline:\n  processors:\n    - mapping: |\n        root = this\n        let key = env("PII_ENCRYPTION_KEY_HEX").decode("hex")\n        let key = if $key.length() != 32 {\n          throw("Expected a 32-byte AES key")\n        } else { $key }\n        let ssn_nonce = uuid_v4().replace_all("-", "").slice(0, 24)\n        let email_nonce = uuid_v4().replace_all("-", "").slice(0, 24)\n        let phone_nonce = uuid_v4().replace_all("-", "").slice(0, 24)\n        let birth_nonce = uuid_v4().replace_all("-", "").slice(0, 24)\n        root.customer.ssn_encrypted = if this.customer.ssn != null {\n          this.customer.ssn.encrypt_aes(\n            "gcm", $key, $ssn_nonce.decode("hex")\n          ).encode("base64")\n        }\n        root.customer.ssn_nonce = if this.customer.ssn != null {\n          $ssn_nonce\n        } else { deleted() }\n        root.customer.ssn_last_four = if this.customer.ssn != null {\n          this.customer.ssn.re_replace_all("[^0-9]", "").slice(-4)\n        }\n        root.customer.email_encrypted = if this.customer.email != null {\n          this.customer.email.encrypt_aes(\n            "gcm", $key, $email_nonce.decode("hex")\n          ).encode("base64")\n        }\n        root.customer.email_nonce = if this.customer.email != null {\n          $email_nonce\n        } else { deleted() }\n        root.customer.email_domain = if this.customer.email != null {\n          this.customer.email.split("@").index(1).lowercase()\n        }\n        root.customer.phone_encrypted = if this.customer.phone != null {\n          this.customer.phone.encrypt_aes(\n            "gcm", $key, $phone_nonce.decode("hex")\n          ).encode("base64")\n        }\n        root.customer.phone_nonce = if this.customer.phone != null {\n          $phone_nonce\n        } else { deleted() }\n        let digits = if this.customer.phone != null {\n          this.customer.phone.re_replace_all("[^0-9]", "")\n        } else { "" }\n        let national = if $digits.length() == 11 && $digits.has_prefix("1") {\n          $digits.slice(1)\n        } else { $digits }\n        root.customer.phone_area_code = if this.customer.phone != null {\n          $national.slice(0, 3)\n        }\n        root.customer.date_of_birth_encrypted = if this.customer.date_of_birth != null {\n          this.customer.date_of_birth.encrypt_aes(\n            "gcm", $key, $birth_nonce.decode("hex")\n          ).encode("base64")\n        }\n        root.customer.date_of_birth_nonce = if this.customer.date_of_birth != null {\n          $birth_nonce\n        } else { deleted() }\n        root.customer.birth_year = if this.customer.date_of_birth != null {\n          this.customer.date_of_birth.split("-").index(0).number()\n        }\n        root.customer = root.customer.without("ssn", "email", "phone", "date_of_birth")\n',
