          'pipeline:\n  processors:\n    - mapping: |\n        root = this\n        let sensitive_found = [\n          if this.payment.card_number != null { "payment.card_number" },\n          if this.payment.cvv != null { "payment.cvv" },\n          if this.customer.ssn != null { "customer.ssn" },\n          if this.customer.email != null { "customer.email" }\n        ].filter(v -> v != null)\n        root = if $sensitive_found.length() > 0 {\n          throw("Encryption validation failed: " + $sensitive_found.join(", "))\n        } else {\n          this\n        }\n    - catch:\n        - mapping: root = deleted()\noutput:\n  broker:\n    pattern: fan_out\n    outputs:\n      - label: payment_processor\n        http_client:\n          url: ${PAYMENT_PROCESSOR_HTTPS_URL}/transactions\n          verb: POST\n          headers:\n            Content-Type: application/json\n            X-Encryption-Version: ${KEY_VERSION}\n            Authorization: Bearer ${PAYMENT_PROCESSOR_TOKEN}\n          tls:\n            enabled: true\n            root_cas_file: ${PAYMENT_PROCESSOR_CA_FILE}\n            client_certs:\n              - cert_file: ${PAYMENT_PROCESSOR_CLIENT_CERT}\n                key_file: ${PAYMENT_PROCESSOR_CLIENT_KEY}\n          batching:\n            count: 50\n            period: 5s\n          retries: 3\n      - label: analytics\n        http_client:\n          url: ${ANALYTICS_HTTPS_URL}/payments\n          verb: POST\n          headers:\n            Content-Type: application/json\n            Authorization: Bearer ${ANALYTICS_API_TOKEN}\n          tls:\n            enabled: true\n            root_cas_file: ${ANALYTICS_CA_FILE}\n          batching:\n            count: 100\n            period: 10s\n',
