        yamlFilename: "03-identity-field-encryption.yaml",
        yamlCode:
          'pipeline:\n  processors:\n    - mapping: |\n        let key = env("PII_ENCRYPTION_KEY_HEX").decode("hex")\n        let key = if $key.length() != 32 { throw("Expected a 32-byte AES key") } else { $key }\n        root = this\n\n        # Extract email domain for B2B analytics\n        root.customer.email_domain = this.customer.email.split("@").index(1)\n        root.customer.email_domain_type = match {\n          root.customer.email_domain.re_match("(gmail|yahoo|hotmail).*") => "consumer"\n          _ => "business"\n        }\n\n        # Phone encryption with area code preservation\n        let phone_clean = this.customer.phone.re_replace_all("[^0-9+]", "")\n        root.customer.phone_country_code = if $phone_clean.has_prefix("+1") { "+1" } else { "international" }\n        root.customer.phone_area_code = if $phone_clean.length() == 12 { $phone_clean.slice(2, 5) }\n\n        # SSN encryption with last 4 preservation\n        let ssn_clean = this.customer.ssn.re_replace_all("[^0-9]", "")\n        root.customer.ssn_last_four = $ssn_clean.slice(-4)\n\n        # Encrypt all PII fields\n        let customer_email_nonce = uuid_v4().replace_all("-", "").slice(0, 24)\n        root.customer.email_encrypted = if this.customer.email != null {\n          this.customer.email.encrypt_aes("gcm", $key, $customer_email_nonce.decode("hex")).encode("base64")\n        }\n        root.customer.email_nonce = if this.customer.email != null { $customer_email_nonce } else { deleted() }\n        let customer_phone_nonce = uuid_v4().replace_all("-", "").slice(0, 24)\n        root.customer.phone_encrypted = if this.customer.phone != null {\n          this.customer.phone.encrypt_aes("gcm", $key, $customer_phone_nonce.decode("hex")).encode("base64")\n        }\n        root.customer.phone_nonce = if this.customer.phone != null { $customer_phone_nonce } else { deleted() }\n        let customer_ssn_nonce = uuid_v4().replace_all("-", "").slice(0, 24)\n        root.customer.ssn_encrypted = if this.customer.ssn != null {\n          this.customer.ssn.encrypt_aes("gcm", $key, $customer_ssn_nonce.decode("hex")).encode("base64")\n        }\n        root.customer.ssn_nonce = if this.customer.ssn != null { $customer_ssn_nonce } else { deleted() }\n        let customer_first_name_nonce = uuid_v4().replace_all("-", "").slice(0, 24)\n        root.customer.first_name_encrypted = if this.customer.first_name != null {\n          this.customer.first_name.encrypt_aes("gcm", $key, $customer_first_name_nonce.decode("hex")).encode("base64")\n        }\n        root.customer.first_name_nonce = if this.customer.first_name != null { $customer_first_name_nonce } else { deleted() }\n        let customer_last_name_nonce = uuid_v4().replace_all("-", "").slice(0, 24)\n        root.customer.last_name_encrypted = if this.customer.last_name != null {\n          this.customer.last_name.encrypt_aes("gcm", $key, $customer_last_name_nonce.decode("hex")).encode("base64")\n        }\n        root.customer.last_name_nonce = if this.customer.last_name != null { $customer_last_name_nonce } else { deleted() }\n\n        # Remove plaintext PII\n        root.customer = root.customer.without("email", "phone", "ssn", "first_name", "last_name")\n',
