        yamlFilename: "04-address-data-encryption-location-privacy.yaml",
        yamlCode:
          'pipeline:\n  processors:\n    - mapping: |\n        let key = env("ADDRESS_ENCRYPTION_KEY_HEX").decode("hex")\n        let key = if $key.length() != 32 { throw("Expected a 32-byte AES key") } else { $key }\n        root = this\n\n        # Extract ZIP prefixes for demographic clustering\n        root.billing_address.zip_prefix = this.billing_address.zip.re_replace_all("[^0-9]", "").slice(0, 3)\n        root.shipping_address.zip_prefix = this.shipping_address.zip.re_replace_all("[^0-9]", "").slice(0, 3)\n\n        # Determine metro areas for regional analytics\n        let billing_metro = match {\n          this.billing_address.city.lowercase().re_match(".*(san francisco|sf).*") => "sf_bay_area"\n          this.billing_address.city.lowercase().re_match(".*(los angeles|la).*") => "la_metro"\n          _ => "other_urban"\n        }\n\n        # Encrypt precise location data\n        let billing_address_street_nonce = uuid_v4().replace_all("-", "").slice(0, 24)\n        root.billing_address.street_encrypted = if this.billing_address.street != null {\n          this.billing_address.street.encrypt_aes("gcm", $key, $billing_address_street_nonce.decode("hex")).encode("base64")\n        }\n        root.billing_address.street_nonce = if this.billing_address.street != null { $billing_address_street_nonce } else { deleted() }\n        let billing_address_zip_nonce = uuid_v4().replace_all("-", "").slice(0, 24)\n        root.billing_address.zip_encrypted = if this.billing_address.zip != null {\n          this.billing_address.zip.encrypt_aes("gcm", $key, $billing_address_zip_nonce.decode("hex")).encode("base64")\n        }\n        root.billing_address.zip_nonce = if this.billing_address.zip != null { $billing_address_zip_nonce } else { deleted() }\n        let shipping_address_street_nonce = uuid_v4().replace_all("-", "").slice(0, 24)\n        root.shipping_address.street_encrypted = if this.shipping_address.street != null {\n          this.shipping_address.street.encrypt_aes("gcm", $key, $shipping_address_street_nonce.decode("hex")).encode("base64")\n        }\n        root.shipping_address.street_nonce = if this.shipping_address.street != null { $shipping_address_street_nonce } else { deleted() }\n        let shipping_address_zip_nonce = uuid_v4().replace_all("-", "").slice(0, 24)\n        root.shipping_address.zip_encrypted = if this.shipping_address.zip != null {\n          this.shipping_address.zip.encrypt_aes("gcm", $key, $shipping_address_zip_nonce.decode("hex")).encode("base64")\n        }\n        root.shipping_address.zip_nonce = if this.shipping_address.zip != null { $shipping_address_zip_nonce } else { deleted() }\n\n        # Address relationship analysis\n        let shipping_metro = match {\n          this.shipping_address.city.lowercase().re_match(".*(san francisco|sf).*") => "sf_bay_area"\n          this.shipping_address.city.lowercase().re_match(".*(los angeles|la).*") => "la_metro"\n          _ => "other_urban"\n        }\n        root.billing_address.metro_area = $billing_metro\n        root.shipping_address.metro_area = $shipping_metro\n        root.address_analysis = {\n          "same_city": this.billing_address.city == this.shipping_address.city,\n          "same_state": this.billing_address.state == this.shipping_address.state,\n          "same_metro": $billing_metro == $shipping_metro\n        }\n\n        # Remove plaintext addresses\n        root.billing_address = root.billing_address.without("street", "zip")\n        root.shipping_address = root.shipping_address.without("street", "zip")\n',
        configSha256:
          "sha256:ac2e05cf3b6314acdafb4d6460ff24e49f9c743948a3358393bff4edd58b485f",
