          'pipeline:\n  processors:\n    - mapping: |\n        root = this\n\n        # Add cell site metadata (from env or lookup)\n        root.cell_id = env("CELL_ID").or("DU_001")\n        root.site_name = env("SITE_NAME").or("tower-downtown-01")\n        root.region = "northeast"\n\n        # Apply authored review bands; these are not engineering conclusions\n        root.within_example_timing_band = this.ptp_offset_ns >= -100 && this.ptp_offset_ns <= 100\n        root.timing_review = if this.ptp_offset_ns >= -100 && this.ptp_offset_ns <= 100 {\n          "inside-example-band"\n        } else if this.ptp_offset_ns >= -1000 && this.ptp_offset_ns <= 1000 {\n          "review"\n        } else {\n          "review-first"\n        }\n\n        root.prb_review = this.prb_dl_util_percent > 90 || this.prb_ul_util_percent > 90\n        root.cpu_review = this.cpu_percent > 80\n',
