    fullYamlFilename: "scada-edge-complete.yaml",
    fullYaml:
      'name: scada-edge-complete\ntype: pipeline\ndescription: Parse synthetic adapter-decoded register records, retain nonzero adapter statuses, add review labels, and route the result.\nnamespace: examples\nlabels:\n  category: integrations\n  pattern: scada-edge-processing\n  industry: energy\n\nconfig:\n  input:\n    socket:\n      network: tcp\n      # The protocol gateway runs as a sidecar or on the same host. Do not\n      # expose the decoded OT feed on the site network.\n      address: 127.0.0.1:4195\n      codec: lines\n\n  pipeline:\n    processors:\n      - mapping: |\n          let fields = content().string().split(";").fold({}, (acc, item) -> {\n            let parts = item.split("=")\n            acc | { parts[0]: parts[1] }\n          })\n          let reg = fields.REG.number()\n          let val = fields.VAL.number()\n\n          root.voltage_kv = if reg == 40001 { val / 100.0 } else { deleted() }\n          root.current_a = if reg == 40003 { val / 10.0 } else { deleted() }\n          root.frequency_hz = if reg == 40005 { val / 100.0 } else { deleted() }\n          root.temp_c = if reg == 40007 { val / 10.0 } else { deleted() }\n          root.power_mw = if reg == 40009 { val / 10.0 } else { deleted() }\n          root.device_id = fields.DEVICE\n          root.register = reg\n          root.raw_value = val\n          root.source_unit = fields.UNIT\n          root.adapter_status = fields.STATUS.number()\n          root."@timestamp" = fields.TS.number()\n\n      - mapping: |\n          if this.adapter_status == 0 {\n            root = deleted()\n          }\n\n      - mapping: |\n          root.review_class = match {\n            this.adapter_status == 2 => "status-2"\n            this.adapter_status == 1 => "status-1"\n            _ => "unclassified-status"\n          }\n          root.pipeline_version = "1.0.0"\n\n  output:\n    broker:\n      outputs:\n        - kafka:\n            addresses: [\'${KAFKA_TLS_BROKERS}\']\n            topic: \'${KAFKA_TOPIC:scada-review-events}\'\n            tls:\n              enabled: true\n              root_cas_file: \'${KAFKA_CA_FILE}\'\n            sasl:\n              mechanism: SCRAM-SHA-512\n              user: \'${KAFKA_USERNAME}\'\n              password: \'${KAFKA_PASSWORD}\'\n        - file:\n            path: \'${SCADA_ARCHIVE_PATH}/scada-review-events.jsonl\'\n            codec: lines\n',
